unsafe fn setBitOfReversedStream(
    mut bitpointer: *mut size_t,
    mut bitstream: *mut c_uchar,
    mut bit: c_uchar,
) {
    let bp = unsafe { &mut *bitpointer }; // SAFETY: caller provides a valid, writable pointer to size_t as required by the original function.
    let p = unsafe { bitstream.add((*bp >> 3 as c_uint) as usize) }; // SAFETY: caller guarantees bitstream points to writable storage for the addressed byte, matching the original offset-based access.
    let mask = ((1 as c_uint) << (7 as size_t).wrapping_sub(*bp & 7 as size_t)) as c_uchar;
    let cur = unsafe { *p }; // SAFETY: p was derived from a valid writable bitstream location as in the original function.
    unsafe {
        // SAFETY: p is a valid writable pointer to the target byte, established above.
        *p = if bit as c_int == 0 as c_int {
            cur & !mask
        } else {
            cur | mask
        };
    }
    *bp = bp.wrapping_add(1);
}

